// 1. 命令侧 - 使用领域模型
public class CreateOrderCommandHandler {
    private final OrderRepository orderRepository;
    private final EventPublisher eventPublisher;

    public OrderId handle(CreateOrderCommand cmd) {
        Order order = Order.create(
            cmd.getCustomerId(),
            cmd.getItems()
        );
        orderRepository.save(order);
        // 发布事件，同步读模型
        eventPublisher.publish(new OrderCreatedEvent(
            order.getId(),
            order.getCustomerId(),
            order.getTotalAmount(),
            order.getCreatedAt()
        ));
        return order.getId();
    }
}

// 2. 查询侧 - 专门的读模型
public class OrderQueryService {
    private final OrderReadRepository readRepo;

    public OrderSummaryDTO getOrderSummary(OrderId orderId) {
        return readRepo.findById(orderId);
    }

    public List<OrderListItemDTO> searchOrders(OrderQuery query) {
        return readRepo.search(query);
    }
}

// 3. 事件处理器 - 同步读模型
@EventHandler
public class OrderReadModelUpdater {
    private final OrderReadRepository readRepo;

    @EventListener
    public void onOrderCreated(OrderCreatedEvent event) {
        OrderReadModel readModel = new OrderReadModel();
        readModel.setOrderId(event.getOrderId());
        readModel.setCustomerId(event.getCustomerId());
        readModel.setTotalAmount(event.getTotalAmount());
        readModel.setCreatedAt(event.getCreatedAt());
        readRepo.save(readModel);
    }
}

// 4. Event Sourcing示例
public class OrderAggregate extends EventSourcedAggregate {
    private OrderStatus status;
    private Money totalAmount;

    public void apply(OrderCreatedEvent event) {
        this.id = event.getOrderId();
        this.status = OrderStatus.CREATED;
        this.totalAmount = event.getTotalAmount();
    }

    public void apply(OrderConfirmedEvent event) {
        this.status = OrderStatus.CONFIRMED;
    }

    public void confirm() {
        if (this.status != OrderStatus.CREATED) {
            throw new DomainException("订单状态不允许确认");
        }
        this.registerEvent(new OrderConfirmedEvent(this.id));
    }
}
